export type SearchTextRange = { start: number; end: number }

/**
 * The place of a space selection in its tab's order (SPEC_TABS.md, В10):
 * the generation of the page that made it, then the page's own count. The
 * page stamps a choice when it makes it, because the commands that carry
 * two choices may start in either order. A page load takes a newer
 * generation (`page_generation`), so a late request of the page it
 * replaced loses to it. Ordered by generation, then by count.
 */
export type SelectionStamp = { generation: number; sequence: number }

/**
 * One rebound command: which key, which modifiers.
 */
export type ShortcutBinding = { key: string; meta?: boolean; shift?: boolean; alt?: boolean; ctrl?: boolean }

/**
 * What asks to show or hide the sidebar of a window's visible tab: sent on
 * to the page as `sidebar-overlay-command` when the sidebar lies over the
 * feed (SPEC_NARROW_WINDOW.md, У4, У6).
 */
export type SidebarIntent =
/**
 * The tab bar's button, View → Hide or Show Sidebar, ⌃⌘S.
 */
{ kind: "toggle" } |
/**
 * A two-finger swipe: right opens, left closes (У11).
 */
{ kind: "swipe"; open: boolean }

/**
 * The sidebar of one tab (РП5, В56: changed 03.10.2026 from one per window).
 */
export type SidebarLayout = { width_px: number; collapsed: boolean }

/**
 * The sidebar of a tab's page as it stands over the feed
 * (SPEC_NARROW_WINDOW.md, У1, У4). The page owns it and reports it
 * (`report_sidebar_overlay`); the backend keeps it in memory only, for the
 * tab bar's button and the View menu, and never saves it (У8).
 */
export type SidebarOverlay =
/**
 * The window holds the sidebar beside the feed: its `collapsed` decides.
 */
"beside" |
/**
 * The window is too narrow for it: the sidebar lies over the feed when
 * open, and is closed now.
 */
"closed" |
/**
 * The sidebar lies over the feed.
 */
"open"

/**
 * One space in the list, with whether it can be opened right now.
 */
export type SpaceEntry = {
/**
 * The space's identity, when the registry knows it.
 */
vault_id: string | null; path: string;
/**
 * The folder name, as the switcher shows it.
 */
name: string;
/**
 * The folder is there and is this space.
 */
available: boolean;
/**
 * The space the app is bound to.
 */
current: boolean }

/**
 * `space-lead-changed`: the tab became or stopped being its space's lead.
 */
export type SpaceLead = { lead: boolean }

/**
 * `space-moved`: the space `vault_id` now lives at `path` (SPEC_TABS.md,
 * В73).
 */
export type SpaceMovedPayload = { vault_id: string; path: string }

/**
 * One rename made by a command.
 */
export type SpaceRename = { kind: RenamedKind; from: string; to: string }

export type SpaceStats = { file_count: number; markdown_count: number; media_count: number; total_bytes: number;
/**
 * From the space's local derived index; `None` when the space has never
 * been opened (no vault-id / no index) or the index predates `card_kind`.
 */
element_count: number | null }

/**
 * A submenu of the menu being opened, as its page counts it from the
 * menu's description (МО28): the largest it gets while the menu is open.
 */
export type SubmenuSize = {
/**
 * How far below the menu's top the submenu's trigger row starts.
 */
row_top: number; width: number; height: number }

/**
 * What one window's tab bar shows (`tabbar-state`).
 */
export type TabBarState = { window_id: WindowId; tabs: TabBarTab[]; active_tab: TabId;
/**
 * The visible tab's sidebar is on screen, beside the feed or over it:
 * what the bar's button shows (В56; SPEC_NARROW_WINDOW.md, У4).
 */
sidebar_shown: boolean; fullscreen: boolean }

/**
 * One tab as the tab bar shows it (В47).
 */
export type TabBarTab = { id: TabId;
/**
 * The space's folder name; `None` for a tab choosing a space.
 */
space_name: string | null;
/**
 * The place the tab is in, as its path names it: the collection or the
 * author (SPEC_CARD_ASSOCIATIONS.md); `None` on Everything.
 */
place: string | null;
/**
 * The title of the card open in the tab; `None` with no card open.
 */
card: string | null;
/**
 * The tab has a page now.
 */
live: boolean;
/**
 * The tab's page has places to go back and forward to (В81). An
 * unloaded tab has neither: its history went with its page.
 */
history: TabHistory }

/**
 * What a tab page needs to start (`get_tab_bootstrap`).
 */
export type TabBootstrap = { tab_id: TabId; window_id: WindowId; space: TabSpace; view: TabView; sidebar: SidebarLayout;
/**
 * The tab leads its space: it does the space's page work and shows its
 * notices (В19).
 */
lead: boolean;
/**
 * No saved windows were read at this launch: the page may carry its
 * old single-window settings over once (В79).
 */
fresh_start: boolean }

/**
 * What the shown tab hears of a file drag over its window.
 */
export type TabFileDrag = { kind: "enter"; paths: string[] } | { kind: "over" } | { kind: "drop"; paths: string[] } | { kind: "leave" }

/**
 * Whether a tab's page can go back and forward through its places (В81).
 */
export type TabHistory = { back: boolean; forward: boolean }

/**
 * Which way the tab bar asks a tab to step through its places (В81).
 */
export type TabHistoryStep = { forward: boolean }

/**
 * A stable tab identity: 32 lowercase hex characters.
 */
export type TabId = string

/**
 * Where in the space a tab is.
 */
export type TabLocation = { kind: "everything" } | { kind: "collection"; tag: string } |
/**
 * The cards of one author, named as written on the card the person came
 * from; compared by `card_association::author_key`
 * (SPEC_CARD_ASSOCIATIONS.md, «Лента автора»).
 */
{ kind: "author"; author: string }

/**
 * Which side of a tab `Close Tabs to the Left` and `Close Tabs to the
 * Right` close (В50).
 */
export type TabSide = "left" | "right"

/**
 * What a tab shows.
 */
export type TabSpace =
/**
 * The space with this identity.
 */
{ kind: "space"; vault_id: string } |
/**
 * Nothing to show: no spaces yet, or the space was forgotten.
 */
{ kind: "picker" }

/**
 * The memory of a tab (Т2): where it is and what it shows.
 */
export type TabView = { location: TabLocation; mode: MainViewMode; open_card: OpenCard | null; scroll_anchor: ScrollAnchor | null; collection_filter: string }

/**
 * `tab-visibility-changed`: the tab was shown or hidden (В41).
 */
export type TabVisibility = { visible: boolean }

/**
 * A tag with its usage count across blocks.
 */
export type TagCount = { tag: string; count: number }

/**
 * Why a task was not toggled (Ч12.3). Nothing was written in any case.
 */
export type TaskToggleError =
/**
 * The tab shows no space.
 */
{ kind: "no_vault" } |
/**
 * The body is not the one the reader saw: the note changed after it
 * was read.
 */
{ kind: "stale_body"; source_slug: string } |
/**
 * The note changed between Mine's read and the publication of the new
 * version; the other version stays.
 */
{ kind: "changed"; source_slug: string } |
/**
 * No task in the state the reader saw starts at `item_start`.
 */
{ kind: "state_changed"; source_slug: string; item_start: number; reason: string } |
/**
 * The note's contents are in iCloud: Mine asked iCloud to download them
 * and did not wait.
 */
{ kind: "in_cloud"; file_name: string } |
/**
 * Mine may not write the note or its folder.
 */
{ kind: "read_only"; file_name: string } |
/**
 * The note is not on disk.
 */
{ kind: "source_not_found"; source_slug: string } | { kind: "internal"; message: string }

export type TaxonomySnapshot = { generation: ProjectionRevision; tags: TagCount[]; channels: ChannelDto[]; total_blocks: number;
/**
 * Which collections each card is in, from the same projection revision
 * as `tags`. See SPEC_CARD_STATES.md, С3 and С4.
 */
memberships: BlockCollection[] }

export type TextSelectionExtractError = { kind: "no_vault" } | { kind: "source_not_found"; source_slug: string } | { kind: "source_not_article"; source_slug: string; block_type: string } | { kind: "empty_selection" } | { kind: "stale_selection" } | { kind: "unsupported_selection_shape"; reason: string } | { kind: "unsafe_source_patch"; reason: string } | { kind: "invalid_collection_ref"; reason: string } |
/**
 * The target collection has no page; nothing was written, neither the
 * new card nor the source article (SPEC_COLLECTIONS_OBSIDIAN_LINKS.md, К7).
 */
{ kind: "collection_not_found"; collection: string } | { kind: "internal"; message: string }

/**
 * A selection made in the editor: exact byte offsets `[start, end)` of the source body (Л11.2).
 */
export type TextSourceRange = { start: number; end: number }

export type ThumbFormat = "jpeg" | "png"

/**
 * What the reading view sends to toggle one task (Ч12.3).
 */
export type ToggleTaskItemParams = {
/**
 * The open card.
 */
source_slug: string;
/**
 * `body_hash` of the body the reader saw.
 */
source_body_hash: string;
/**
 * The byte offset in that body where the task's list item starts: its
 * list marker, after `> ` in a quote or a callout.
 */
item_start: number;
/**
 * The state the reader saw: `true` for a done task.
 */
checked: boolean }

/**
 * A space that is bound but not reachable right now. Also the payload of
 * `space-unavailable`, which names the lost space so a window can ignore a
 * report about a space it no longer shows (`SPEC_AUDIT_FIXES.md`, В2.1).
 */
export type UnavailableVault = {
/**
 * The path the space was opened with, spelled as `vault-selected` and
 * `get_vault_path` report it.
 */
path: string;
/**
 * Why the space cannot be opened: the folder is gone from this path, or
 * it is right there and macOS refuses to let the app read it. The two
 * need different words and different actions — "locate the folder" is
 * useless advice when the folder is visible and locked.
 * See SPEC_ONBOARDING.md О11.
 */
reason: UnavailableVaultReason;
/**
 * The lost space's identity, when the app knows it.
 */
vault_id: string | null }

export type UnavailableVaultReason =
/**
 * Renamed, moved, on a disconnected drive, or not yet synced.
 */
"missing" |
/**
 * The folder exists; reading it is what fails.
 */
"access_denied" |
/**
 * A folder stands at the path and can be read, but it is not this
 * space: its identity file `.mine/vault-id` is gone, or names another
 * space (SPEC_DEEP_AUDIT.md, Е2.13).
 */
"not_this_space"

/**
 * Failures are distinct; a signed staged archive is never reported as installed.
 */
export type UpdateError = { kind: "disabled" } | { kind: "configuration"; detail: string } | { kind: "busy" } | { kind: "no_update" } | { kind: "transport"; detail: string } | { kind: "signature"; detail: string } | { kind: "storage"; detail: string } | { kind: "journal"; detail: string } | { kind: "archive_changed" } | { kind: "activation"; detail: string }

/**
 * Persisted download lifecycle, separate from installation and activation.
 */
export type UpdateStage = "disabled" | "idle" | "checking" | "available" | "downloading" | "verified" | "installing" | "restarting" | "activated" | "rolled_back" | "recovery_required" | "failed"

/**
 * Content-free updater status for local diagnostics and a future settings UI.
 */
export type UpdateStatus = { stage: UpdateStage; version: string | null; notes: string | null; downloaded_bytes: number; total_bytes: number | null; archive_sha256: string | null; error: UpdateError | null; activation_available: boolean }

/**
 * `vault-changed`: the sources of the space at `path` changed. `renames`
 * lists what a command renamed; the watcher's news carries none.
 */
export type VaultChangedPayload = { path: string; renames: SpaceRename[] }

/**
 * A note in conflict, as the window shows it (ВК7).
 */
export type VaultConflict = {
/**
 * From the space root, with folders: `Cards/Note.md`.
 */
path: string;
/**
 * The note's name: `Note`.
 */
name: string; detected_at: string;
/**
 * The version in the folder.
 */
current: ConflictVersion;
/**
 * The hidden conflict versions.
 */
versions: ConflictVersion[];
/**
 * iCloud did not answer about the note this time: the conflict stays
 * recorded and counted, no version can be kept until it answers
 * (SPEC_DEEP_AUDIT.md, Е5.12).
 */
unanswered: boolean }

/**
 * Why a conflict was not listed or resolved (ВК12).
 */
export type VaultConflictError = { kind: "no_vault" } |
/**
 * The path is not a note of the space.
 */
{ kind: "invalid_path"; path: string } |
/**
 * No conflict is recorded for the path any more.
 */
{ kind: "not_pending"; path: string } |
/**
 * The versions differ from those the window showed. Nothing changed.
 */
{ kind: "versions_changed"; path: string } |
/**
 * The note changed on disk after it was read. Nothing changed.
 */
{ kind: "source_changed"; path: string } | { kind: "helper_failed"; message: string } |
/**
 * The conflict is resolved, but the Trash refused the other versions:
 * they stay next to the note as separate notes, `paths`.
 */
{ kind: "trash_failed"; paths: string[] } | { kind: "internal"; message: string }

/**
 * `vault-conflicts-changed`: how many notes of the space are in conflict now.
 */
export type VaultConflictsChanged = { count: number }

/**
 * `vault-freshness-changed`: a pass of the space against its files ended.
 */
export type VaultFreshnessChanged = { vault_path: string; generation: number;
/**
 * `fresh`, `degraded` (some notes failed) or `failed` (the pass failed).
 */
state: string; joined_callers: number; inventory_markdown: number; content_reads: number; database_writes: number; error_count: number;
/**
 * The notes the pass could not read or project, with why: the index is
 * ready without them (SPEC_DEEP_AUDIT.md, Н6), and the interface names
 * them (Е6.17).
 */
error_files: ReconcileFileError[]; elapsed_ms: number; fast_path_hits: number }

export type VaultOpenResult = { indexed: number; errors: number; sync_in_progress: boolean;
/**
 * The index holds a finished snapshot. False while the first pass
 * builds it: the opening notice is then the only sign (Х28).
 */
derived_store_ready: boolean; thumbs_root: string }

/**
 * Folders new files are written into, relative to the vault root.
 *
 * Reading never depends on this: the scanner walks the whole vault and a
 * card's identity is its path, wherever it sits. This governs writes only —
 * where the clipper, the app and new collection documents put new files.
 *
 * An empty string means the vault root, which is both the historical layout
 * and a legitimate configuration: a user may point all three at the root and
 * keep everything flat. See SPEC_VAULT_LIFECYCLE.md П1–П4.
 */
export type VaultWriteLayout = { cards?: string; media?: string; collections?: string }

export type VaultWriteLayoutDto = { cards: string; media: string; collections: string }

/**
 * A poster of a video the body shows.
 */
export type VideoPosterRef = { video_url: string; poster_url: string }

/**
 * A stable window identity: 32 lowercase hex characters.
 */
export type WindowId = string
